"""Generate the next order id from ids.txt.

Ids are sequential base-36 codes (ORD-XXXX), read from ids.txt (most recent last).
"""

import pathlib

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int, width: int = 4) -> str:
    """Format an integer as a zero-padded base-36 string."""
    chars = []
    for _ in range(width):
        chars.append(DIGITS[n % 36])
        n //= 36
    return "".join(reversed(chars))


def main() -> None:
    text = pathlib.Path("ids.txt").read_text(encoding="utf-8")
    last_id = None

    for line in text.splitlines():
        if not line.strip():
            continue
        parts = line.split("\t")
        if len(parts) >= 2:
            candidate = parts[-1].strip()
        else:
            candidate = parts[0].strip()
        if candidate.startswith("ORD-") and len(candidate) == 8:
            suffix = candidate[4:]
            if all(c in DIGITS for c in suffix):
                last_id = suffix

    if last_id is None:
        # No valid ID found — start from the beginning
        next_suffix = "0000"
    else:
        n = int(last_id, 36)
        next_suffix = to_base36(n + 1)

    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

