import sys


def to_base36(num: int) -> str:
    """Convert an integer to a base-36 string using 0-9, A-Z."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if num == 0:
        return "0"
    result = []
    while num > 0:
        result.append(chars[num % 36])
        num //= 36
    return "".join(reversed(result))


def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    return int(s, 36)


def main():
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    suffix = last_id.split("-")[1]
    next_num = from_base36(suffix) + 1
    next_suffix = to_base36(next_num).zfill(4)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

