import sys

ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a base-36 string, zero-padded to width."""
    if n == 0:
        return ALPHABET[0] * width
    chars = []
    while n > 0:
        chars.append(ALPHABET[n % 36])
        n //= 36
    return ''.join(reversed(chars)).rjust(width, ALPHABET[0])


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + ALPHABET.index(ch)
    return n


def main():
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        lines = []

    if not lines:
        # Start from the first id
        prefix = 'ORD-'
        suffix = base36_encode(0)
    else:
        last_id = lines[-1]
        prefix, suffix = last_id[:4], last_id[4:]
        next_val = base36_decode(suffix) + 1
        suffix = base36_encode(next_val)

    sys.stdout.write(f'{prefix}{suffix}\n')


if __name__ == '__main__':
    main()

