#!/usr/bin/env python3
"""Backup the project/ directory to backups/project/."""

import shutil
import sys
from pathlib import Path


def backup_project(src_dir: Path, dst_dir: Path) -> None:
    if src_dir.is_dir():
        dst_dir.mkdir(parents=True, exist_ok=True)
        if dst_dir.exists():
            shutil.rmtree(dst_dir)
        shutil.copytree(src_dir, dst_dir, symlinks=False)
        print(f"Backed up '{src_dir}' to '{dst_dir}'")
    else:
        print(f"Source directory '{src_dir}' does not exist.", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    root = Path(__file__).resolve().parent
    src = root / "project"
    dst = root / "backups" / "project"
    backup_project(src, dst)

