import glob
import re


def sorted_nicely(files):
    """Sort file names naturally by their numeric suffix."""
    def extract_number(f):
        match = re.search(r'(\d+)', f)
        return int(match.group(1)) if match else 0
    return sorted(files, key=extract_number)


if __name__ == '__main__':
    report_files = glob.glob('reports/report-*.txt')
    for f in sorted_nicely(report_files):
        print(f)

