import sys
from datetime import datetime, timezone

def parse_timestamp(line):
    """Extract the timestamp from a log line."""
    if len(line) < 19:
        return None
    ts_str = line[:19]
    try:
        return datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff_dt = as_of_dt.timestamp() - 7 * 86400
    cutoff_dt_obj = datetime.fromtimestamp(cutoff_dt, tz=timezone.utc)

    app_log_path = "app.log"
    archive_log_path = "archive.log"

    with open(app_log_path, "r") as f:
        lines = f.readlines()

    old_entries = []
    new_entries = []

    for line in lines:
        if not line.strip():
            continue
        ts = parse_timestamp(line)
        if ts is None:
            new_entries.append(line)
        elif ts < cutoff_dt_obj:
            old_entries.append(line)
        else:
            new_entries.append(line)

    with open(archive_log_path, "a") as f:
        for entry in old_entries:
            f.write(entry)

    with open(app_log_path, "w") as f:
        for entry in new_entries:
            f.write(entry)

if __name__ == "__main__":
    main()

